CREATE OR REPLACE FUNCTION public.kumeel_send_comment(p_post uuid, p_name text, p_body text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=kumeel_private.community_actor(); result uuid;
begin
 perform 1 from public.kumeel_community_posts where id=p_post for key share;
 if not found then raise exception 'COMMUNITY_NOT_PUBLISHED'; end if;
 perform kumeel_private.community_limit(actor,'comment');
 insert into public.kumeel_community_comments(post_id,author_id,author_name,body) values(p_post,actor,btrim(p_name),btrim(p_body)) returning id into result;
 return result;
end; $function$

CREATE OR REPLACE FUNCTION public.kumeel_chat_take(p_secret text, p_visitor text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 s kumeel_private.chat_settings;
 q kumeel_private.chat_quota;
 used integer;
begin
 select * into s from kumeel_private.chat_settings where id = 1;
 if not found then raise exception 'CHAT_NOT_CONFIGURED' using errcode = 'P0001'; end if;
 if p_secret is null or encode(extensions.digest(p_secret, 'sha256'), 'hex') <> s.secret_hash then
  raise exception 'CHAT_FORBIDDEN' using errcode = '42501';
 end if;
 if not s.enabled then return 'disabled'; end if;
 if p_visitor is null or p_visitor !~ '^[0-9a-f]{64}$' then raise exception 'CHAT_BAD_VISITOR' using errcode = '22023'; end if;

 -- Global cap first so a burst cannot exceed the provider quota.
 insert into kumeel_private.chat_usage(day) values (current_date) on conflict do nothing;
 select count into used from kumeel_private.chat_usage where day = current_date for update;
 if used >= s.global_per_day then return 'global'; end if;

 insert into kumeel_private.chat_quota(visitor) values (p_visitor) on conflict do nothing;
 select * into q from kumeel_private.chat_quota where visitor = p_visitor for update;
 if q.day <> current_date then q.day_count := 0; end if;
 if now() - q.window_start >= interval '1 minute' then q.window_start := now(); q.window_count := 0; end if;
 if q.day_count >= s.per_day then return 'day'; end if;
 if q.window_count >= s.per_minute then return 'minute'; end if;

 update kumeel_private.chat_quota
  set day = current_date, day_count = q.day_count + 1, window_start = q.window_start, window_count = q.window_count + 1
  where visitor = p_visitor;
 update kumeel_private.chat_usage set count = used + 1 where day = current_date;
 -- Keep only recent counters.
 if used = 0 then
  delete from kumeel_private.chat_quota where day < current_date - 2;
  delete from kumeel_private.chat_usage where day < current_date - 30;
 end if;
 return 'ok';
end; $function$

CREATE OR REPLACE FUNCTION public.kumeel_send_writing_response(p_writing text, p_name text, p_body text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=kumeel_private.community_actor(); result uuid;
begin
 -- Only writings in the public snapshot accept opinions; starter templates have no reader page.
 if p_writing is null or not exists(
  select 1 from public.kumeel_published p
  cross join lateral jsonb_array_elements(case when jsonb_typeof(p.content->'writings')='array' then p.content->'writings' else '[]'::jsonb end) w
  where p.id='main' and w->>'id'=p_writing) then
  raise exception 'COMMUNITY_NOT_PUBLISHED';
 end if;
 perform kumeel_private.community_limit(actor,'comment');
 insert into public.kumeel_writing_responses(writing_id,author_id,author_name,body) values(p_writing,actor,btrim(p_name),btrim(p_body)) returning id into result;
 return result;
end; $function$

