CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
  tbl name;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        SELECT c.relname INTO tbl FROM pg_catalog.pg_class c WHERE c.oid = cmd.objid;
        EXECUTE format('alter table if exists %I.%I enable row level security', cmd.schema_name, tbl);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION kumeel_private.community_limit(actor uuid, kind text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare q kumeel_private.community_quota;
begin
 insert into kumeel_private.community_quota(user_id) values(actor) on conflict do nothing;
 select * into q from kumeel_private.community_quota where user_id=actor for update;
 if q.day<>current_date then q.posts:=0;q.comments:=0;q.writes:=0; end if;
 if q.writes>=100 or (kind='post' and q.posts>=5) or (kind='comment' and q.comments>=20) then
  raise exception 'COMMUNITY_LIMIT' using errcode='P0001';
 end if;
 update kumeel_private.community_quota set day=current_date,posts=q.posts+(case when kind='post' then 1 else 0 end),
 comments=q.comments+(case when kind='comment' then 1 else 0 end),writes=q.writes+1 where user_id=actor;
end; $function$

CREATE OR REPLACE FUNCTION kumeel_private.community_actor()
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid();
begin
 if not public.kumeel_has_active_session() or actor is null or not exists(select 1 from auth.users where id=actor and email_confirmed_at is not null) then
  raise exception 'COMMUNITY_AUTH' using errcode='42501';
 end if;
 return actor;
end; $function$

CREATE OR REPLACE FUNCTION public.kumeel_save_submission(p_id uuid, p_revision integer, p_name text, p_title text, p_body text, p_category text, p_sources text, p_assisted boolean, p_submit boolean, p_rights boolean)
 RETURNS kumeel_submissions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=kumeel_private.community_actor(); item public.kumeel_submissions;
begin
 if p_submit and (not coalesce(p_rights,false) or char_length(btrim(p_body))<80) then raise exception 'COMMUNITY_CONTENT'; end if;
 if p_id is null then
  perform kumeel_private.community_limit(actor,'post');
  insert into public.kumeel_submissions(author_id,author_name,title,body,category,sources,assisted,rights_confirmed,status)
  values(actor,btrim(p_name),btrim(p_title),p_body,p_category,p_sources,p_assisted,p_rights,case when p_submit then 'pending' else 'draft' end) returning * into item;
 else
  select * into item from public.kumeel_submissions where id=p_id and author_id=actor for update;
  if not found then raise exception 'COMMUNITY_FORBIDDEN' using errcode='42501'; end if;
  if item.revision is distinct from p_revision then raise exception 'COMMUNITY_CONFLICT'; end if;
  if item.status not in ('draft','changes_requested') then raise exception 'COMMUNITY_LOCKED'; end if;
  perform kumeel_private.community_limit(actor,'write');
  update public.kumeel_submissions set author_name=btrim(p_name),title=btrim(p_title),body=p_body,category=p_category,
   sources=p_sources,assisted=p_assisted,rights_confirmed=p_rights,status=case when p_submit then 'pending' else 'draft' end,
   revision=revision+1,updated_at=now() where id=p_id returning * into item;
 end if;
 return item;
end; $function$

CREATE OR REPLACE FUNCTION public.kumeel_review_community(p_kind text, p_id uuid, p_revision integer, p_decision text, p_note text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=kumeel_private.community_actor(); item public.kumeel_submissions; reply public.kumeel_community_comments;
begin
 if not public.kumeel_is_secure_editor() then raise exception 'COMMUNITY_FORBIDDEN' using errcode='42501'; end if;
 if p_decision is null or p_decision not in ('published','changes_requested','rejected') or p_note is null or char_length(p_note)>1000 then raise exception 'COMMUNITY_CONTENT'; end if;
 if p_decision<>'published' and char_length(btrim(p_note))<3 then raise exception 'COMMUNITY_NOTE_REQUIRED'; end if;
 if p_kind='post' then
  select * into item from public.kumeel_submissions where id=p_id for update;
  if not found then raise exception 'COMMUNITY_NOT_FOUND'; end if;
  if item.revision is distinct from p_revision then raise exception 'COMMUNITY_CONFLICT'; end if;
  if item.status not in ('pending','published') or (p_decision='published' and item.status<>'pending') then raise exception 'COMMUNITY_LOCKED'; end if;
  if p_decision='published' then
   if not item.rights_confirmed or char_length(btrim(item.body))<80 then raise exception 'COMMUNITY_CONTENT'; end if;
   insert into public.kumeel_community_posts(id,author_name,title,body,category,sources,assisted)
    values(item.id,item.author_name,item.title,item.body,item.category,item.sources,item.assisted);
  else
   delete from public.kumeel_community_posts where id=p_id;
   -- Removing a post hides its comments; they must be reviewed again after republication.
   update public.kumeel_community_comments set status='pending',revision=revision+1 where post_id=p_id and status='published';
  end if;
  update public.kumeel_submissions set status=p_decision,review_note=btrim(p_note),revision=revision+1,updated_at=now() where id=p_id;
 elsif p_kind='comment' then
  if p_decision='changes_requested' then raise exception 'COMMUNITY_CONTENT'; end if;
  -- Lock the parent before the comment to serialize moderation with post withdrawal.
  select s.* into item from public.kumeel_submissions s join public.kumeel_community_comments c on c.post_id=s.id where c.id=p_id for update of s;
  select * into reply from public.kumeel_community_comments where id=p_id for update;
  if not found then raise exception 'COMMUNITY_NOT_FOUND'; end if;
  if reply.revision is distinct from p_revision then raise exception 'COMMUNITY_CONFLICT'; end if;
  if reply.status not in ('pending','published') or (p_decision='published' and reply.status<>'pending') then raise exception 'COMMUNITY_LOCKED'; end if;
  if p_decision='published' then
   if item.status<>'published' then raise exception 'COMMUNITY_NOT_PUBLISHED'; end if;
   insert into public.kumeel_public_comments(id,post_id,author_name,body) values(reply.id,reply.post_id,reply.author_name,reply.body);
  else delete from public.kumeel_public_comments where id=p_id; end if;
  update public.kumeel_community_comments set status=p_decision,revision=revision+1 where id=p_id;
 else raise exception 'COMMUNITY_CONTENT'; end if;
 insert into public.kumeel_review_log(item_id,item_kind,reviewer_id,decision,note,revision) values(p_id,p_kind,actor,p_decision,btrim(p_note),p_revision);
end; $function$

CREATE OR REPLACE FUNCTION public.kumeel_apply_teacher(p_revision integer, p_name text, p_specialty text, p_bio text, p_approach text, p_audience text, p_languages text, p_qualifications text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=kumeel_private.community_actor(); old public.kumeel_teacher_applications;
begin
 -- Serialize both initial creation and subsequent edits for this account.
 perform 1 from auth.users where id=actor for update;
 select * into old from public.kumeel_teacher_applications where user_id=actor for update;
 if found then
  if old.revision is distinct from p_revision then raise exception 'COMMUNITY_CONFLICT'; end if;
  if old.status not in ('published','changes_requested') then raise exception 'COMMUNITY_LOCKED'; end if;
  perform kumeel_private.community_limit(actor,'write');
  update public.kumeel_teacher_applications set name=btrim(p_name),specialty=btrim(p_specialty),bio=btrim(p_bio),approach=btrim(p_approach),audience=btrim(p_audience),languages=btrim(p_languages),qualifications=p_qualifications,status='pending',revision=revision+1,updated_at=now() where user_id=actor;
 else
  perform kumeel_private.community_limit(actor,'write');
  insert into public.kumeel_teacher_applications(user_id,name,specialty,bio,approach,audience,languages,qualifications) values(actor,btrim(p_name),btrim(p_specialty),btrim(p_bio),btrim(p_approach),btrim(p_audience),btrim(p_languages),p_qualifications);
 end if;
 -- An approved profile remains visible unchanged until the revised application is reviewed.
end; $function$

CREATE OR REPLACE FUNCTION public.kumeel_review_teacher(p_user uuid, p_revision integer, p_decision text, p_note text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=kumeel_private.community_actor(); item public.kumeel_teacher_applications;
begin
 if not public.kumeel_is_secure_editor() then raise exception 'COMMUNITY_FORBIDDEN' using errcode='42501';end if;
 if p_decision is null or p_decision not in ('published','changes_requested','rejected') or p_note is null or char_length(p_note)>1000 then raise exception 'COMMUNITY_CONTENT';end if;
 if p_decision<>'published' and char_length(btrim(p_note))<3 then raise exception 'COMMUNITY_NOTE_REQUIRED';end if;
 select * into item from public.kumeel_teacher_applications where user_id=p_user for update;
 if not found then raise exception 'COMMUNITY_NOT_FOUND';end if;
 if item.revision is distinct from p_revision then raise exception 'COMMUNITY_CONFLICT';end if;
 if item.status not in ('pending','published') or (item.status='published' and p_decision='published') then raise exception 'COMMUNITY_LOCKED';end if;
 if p_decision='published' then
  insert into public.kumeel_teacher_profiles(application_id,name,specialty,bio,approach,audience,languages)
  values(item.user_id,item.name,item.specialty,item.bio,item.approach,item.audience,item.languages)
  on conflict(application_id) do update set name=excluded.name,specialty=excluded.specialty,bio=excluded.bio,approach=excluded.approach,audience=excluded.audience,languages=excluded.languages;
 else delete from public.kumeel_teacher_profiles where application_id=p_user;end if;
 update public.kumeel_teacher_applications set status=p_decision,review_note=btrim(p_note),revision=revision+1,updated_at=now() where user_id=p_user;
 insert into public.kumeel_review_log(item_id,item_kind,reviewer_id,decision,note,revision) values(p_user,'teacher',actor,p_decision,btrim(p_note),p_revision);
end; $function$

CREATE OR REPLACE FUNCTION public.kumeel_valid_public_translations(document jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare k text; r jsonb; w jsonb; bytes bytea; expected text;
begin
 if jsonb_typeof(document) is distinct from 'object' or document ? 'translationDrafts' then return false; end if;
 if not document ? 'translations' then return true; end if;
 if jsonb_typeof(document->'translations') is distinct from 'object' then return false; end if;
 if jsonb_typeof(document->'writings') is distinct from 'array' then return false; end if;
 if (select count(*) from jsonb_object_keys(document->'translations'))>501 then return false; end if;
 for k,r in select * from jsonb_each(document->'translations') loop
  if jsonb_typeof(r) is distinct from 'object' then return false; end if;
  if (select count(*) from jsonb_object_keys(r))<>4 or not r ?& array['locale','title','text','sourceHash'] then return false; end if;
  if r->>'locale' is distinct from 'en' or jsonb_typeof(r->'title') is distinct from 'string'
   or jsonb_typeof(r->'text') is distinct from 'string' or jsonb_typeof(r->'sourceHash') is distinct from 'string'
   or length(r->>'title')>300 or length(r->>'text')>60000 or length(btrim(r->>'text'))=0
   or r->>'sourceHash' !~ '^[0-9a-f]{64}$' then return false; end if;
  if k='bio' then
   if jsonb_typeof(document->'bio') is distinct from 'string' then return false;end if;
   bytes:=convert_to(E'kumeel-translation-v1\nbio\n'||(document->>'bio'),'UTF8');
  elsif left(k,8)='writing:' and length(k) between 9 and 158 then
   if length(btrim(r->>'title'))=0 then return false;end if;
   select item into w from jsonb_array_elements(document->'writings') item where item->>'id'=substr(k,9);
   if w is null or jsonb_typeof(w->'title') is distinct from 'string' or jsonb_typeof(w->'text') is distinct from 'string' then return false;end if;
   if coalesce(w->>'format','plain') not in ('plain','markdown') then return false;end if;
   bytes:=convert_to(E'kumeel-translation-v1\nwriting\n'||(w->>'title'),'UTF8')||decode('00','hex')
    ||convert_to(w->>'text','UTF8')||decode('00','hex')||convert_to(coalesce(w->>'format','plain'),'UTF8');
  else return false; end if;
  expected:=encode(extensions.digest(bytes,'sha256'),'hex');
  if r->>'sourceHash' is distinct from expected then return false;end if;
 end loop;
 return true;
end $function$

CREATE OR REPLACE FUNCTION public.kumeel_review_writing_response(p_id uuid, p_revision integer, p_decision text, p_note text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=kumeel_private.community_actor(); reply public.kumeel_writing_responses;
begin
 if not public.kumeel_is_secure_editor() then raise exception 'COMMUNITY_FORBIDDEN' using errcode='42501'; end if;
 if p_decision is null or p_decision not in ('published','rejected') or p_note is null or char_length(p_note)>1000 then raise exception 'COMMUNITY_CONTENT'; end if;
 if p_decision='rejected' and char_length(btrim(p_note))<3 then raise exception 'COMMUNITY_NOTE_REQUIRED'; end if;
 select * into reply from public.kumeel_writing_responses where id=p_id for update;
 if not found then raise exception 'COMMUNITY_NOT_FOUND'; end if;
 if reply.revision is distinct from p_revision then raise exception 'COMMUNITY_CONFLICT'; end if;
 if reply.status not in ('pending','published') or (p_decision='published' and reply.status<>'pending') then raise exception 'COMMUNITY_LOCKED'; end if;
 if p_decision='published' then
  insert into public.kumeel_public_writing_responses(id,writing_id,author_name,body) values(reply.id,reply.writing_id,reply.author_name,reply.body);
 else delete from public.kumeel_public_writing_responses where id=p_id; end if;
 update public.kumeel_writing_responses set status=p_decision,revision=revision+1 where id=p_id;
 insert into public.kumeel_review_log(item_id,item_kind,reviewer_id,decision,note,revision) values(p_id,'writing_response',actor,p_decision,btrim(p_note),p_revision);
end; $function$

CREATE OR REPLACE FUNCTION public.kumeel_save_sparring(p_id uuid, p_revision integer, p_writing text, p_style text, p_turns jsonb)
 RETURNS kumeel_sparring
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare item public.kumeel_sparring;
begin
 if not public.kumeel_is_secure_editor() then raise exception 'COMMUNITY_FORBIDDEN' using errcode='42501'; end if;
 if not kumeel_private.valid_sparring_turns(p_turns) then raise exception 'COMMUNITY_CONTENT'; end if;
 if p_id is null then
  insert into public.kumeel_sparring(writing_id,style,turns) values(p_writing,p_style,p_turns) returning * into item;
 else
  select * into item from public.kumeel_sparring where id=p_id for update;
  if not found then raise exception 'COMMUNITY_NOT_FOUND'; end if;
  if item.revision is distinct from p_revision then raise exception 'COMMUNITY_CONFLICT'; end if;
  update public.kumeel_sparring set turns=p_turns,revision=revision+1,updated_at=now() where id=p_id returning * into item;
 end if;
 return item;
end; $function$

CREATE OR REPLACE FUNCTION public.kumeel_owner_ai_take(p_secret text, p_actor uuid, p_scope text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare limits kumeel_private.owner_ai_limits; quota kumeel_private.owner_ai_quota; stamp timestamptz; local_day date; retry integer;
begin
 if p_secret is null or char_length(p_secret) not between 32 and 256 or not exists(select 1 from kumeel_private.chat_settings s where s.id=1 and s.secret_hash=encode(extensions.digest(p_secret,'sha256'),'hex')) then
  raise exception 'QUOTA_FORBIDDEN' using errcode='42501';
 end if;
 if not exists(select 1 from public.kumeel_editors e join auth.users u on u.id=e.user_id where u.id=p_actor and u.email_confirmed_at is not null and lower(u.email) in ('komeil9060@gmail.com','bobmorgann2@gmail.com')) then
  raise exception 'QUOTA_FORBIDDEN' using errcode='42501';
 end if;
 select * into limits from kumeel_private.owner_ai_limits where scope=p_scope;
 if not found then raise exception 'QUOTA_SCOPE' using errcode='22023'; end if;
 insert into kumeel_private.owner_ai_quota(actor,scope) values(p_actor,p_scope) on conflict do nothing;
 select * into quota from kumeel_private.owner_ai_quota where actor=p_actor and scope=p_scope for update;
 stamp=clock_timestamp();local_day=(stamp at time zone 'Asia/Riyadh')::date;
 if quota.day<>local_day then quota.used=0;end if;
 if quota.used>=limits.per_day then
  retry=greatest(1,ceil(extract(epoch from((((local_day+1)::timestamp at time zone 'Asia/Riyadh')-stamp))))::integer);
  return jsonb_build_object('allowed',false,'reason','daily','retry_after',retry,'remaining',0);
 end if;
 if quota.last_request is not null and stamp-quota.last_request<make_interval(secs=>limits.cooldown_seconds) then
  retry=greatest(1,ceil(limits.cooldown_seconds-extract(epoch from(stamp-quota.last_request)))::integer);
  return jsonb_build_object('allowed',false,'reason','cooldown','retry_after',retry,'remaining',limits.per_day-quota.used);
 end if;
 update kumeel_private.owner_ai_quota set day=local_day,used=quota.used+1,last_request=stamp where actor=p_actor and scope=p_scope;
 return jsonb_build_object('allowed',true,'retry_after',0,'remaining',limits.per_day-quota.used-1);
end;
$function$
